local SulfurCollector = {}
local PRODUCTS = {
    raw_sulfur = { name = "Surovo žveplo", oreCost = 2, time = 1, cost = 12, purity = 30, description = "Surovo žveplo iz vulkanskih nahajališč." },
    melted_sulfur = { name = "Raztaljeno žveplo", oreCost = 3, fuelCost = 1, time = 3, cost = 35, purity = 50, prestige = 1, description = "Raztaljeno žveplo za smodek." },
    refined_sulfur = { name = "Rafinirano žveplo", oreCost = 3, fuelCost = 2, time = 5, cost = 95, purity = 70, prestige = 3, happiness = 1, description = "Rafinirano žveplo z visoko čistostjo." },
    sublimed_sulfur = { name = "Sublimirano žveplo", oreCost = 4, fuelCost = 2, time = 7, cost = 230, purity = 85, prestige = 6, happiness = 2, description = "Sublimirano žveplo za fine smodnike." },
    silver_treated_sulfur = { name = "Srebrno obdelano žveplo", oreCost = 4, fuelCost = 2, silverCost = 1, time = 10, cost = 520, purity = 95, prestige = 12, happiness = 3, description = "Srebrno obdelano žveplo za kraljeve smodnike." },
    royal_pure_sulfur = { name = "Kraljevski čisto žveplo", oreCost = 6, fuelCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, time = 15, cost = 1300, purity = 100, prestige = 35, happiness = 8, description = "Veliko kraljevsko čisto žveplo z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Žveplovka delavnica", cost = { gold = 280, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    smelting_room = { name = "Talilnica", cost = { gold = 950, wood = 280, stone = 500, iron = 8 }, upkeep = 22, qualityBonus = 18 },
    sublimation_room = { name = "Sublimirnica", cost = { gold = 2300, wood = 500, stone = 700, silver = 40, fuel = 10 }, upkeep = 55, qualityBonus = 30 },
    royal_sulfur_atelier = { name = "Kraljevski atelje žvepla", cost = { gold = 9500, wood = 800, stone = 1500, gold = 80, jewel = 25 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
SulfurCollector.oreStock = 16; SulfurCollector.fuelStock = 14; SulfurCollector.silverStock = 8; SulfurCollector.goldStock = 6; SulfurCollector.jewelStock = 6
SulfurCollector.productStock = {}; SulfurCollector.buildings = {}; SulfurCollector.maker = nil; SulfurCollector.activeMaking = {}; SulfurCollector.totalProducts = 0; SulfurCollector.dayTimer = 0
function SulfurCollector.init() SulfurCollector.oreStock=16; SulfurCollector.fuelStock=14; SulfurCollector.silverStock=8; SulfurCollector.goldStock=6; SulfurCollector.jewelStock=6; SulfurCollector.productStock={}; SulfurCollector.buildings={}; SulfurCollector.maker=nil; SulfurCollector.activeMaking={}; SulfurCollector.totalProducts=0; SulfurCollector.dayTimer=0; print("[SulfurCollector] Royal Sulfur Collector System initialized (6 products, 4 buildings)") end
function SulfurCollector.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SulfurCollector.maker={name=n or ("Žveplar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žveplar najet: %s (spretnost: %d)",SulfurCollector.maker.name,s),"success") end; return true end
function SulfurCollector.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SulfurCollector.build(id) local ok,e=SulfurCollector.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SulfurCollector.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SulfurCollector.getQualityBonus() local b=0; for _,bd in ipairs(SulfurCollector.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SulfurCollector.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.oreCost and SulfurCollector.oreStock<(d.oreCost or 0) then return false,"Premalo rude" end; if d.fuelCost and SulfurCollector.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.silverCost and SulfurCollector.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SulfurCollector.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SulfurCollector.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #SulfurCollector.buildings==0 then return false,"Potrebna delavnica" end; if not SulfurCollector.maker then return false,"Potreben žveplar" end; return true end
function SulfurCollector.make(pt,qty) qty=qty or 5; local ok,e=SulfurCollector.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.oreCost then SulfurCollector.oreStock=SulfurCollector.oreStock-d.oreCost*qty end; if d.fuelCost then SulfurCollector.fuelStock=SulfurCollector.fuelStock-d.fuelCost*qty end; if d.silverCost then SulfurCollector.silverStock=SulfurCollector.silverStock-d.silverCost*qty end; if d.goldCost then SulfurCollector.goldStock=SulfurCollector.goldStock-d.goldCost*qty end; if d.jewelCost then SulfurCollector.jewelStock=SulfurCollector.jewelStock-d.jewelCost*qty end; local t=d.time; if SulfurCollector.maker then t=math.max(1,t-math.floor(SulfurCollector.maker.skill/12)) end; table.insert(SulfurCollector.activeMaking,{id="sulfur_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,purity=d.purity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SulfurCollector.completeMaking(m) local q=1.0+(SulfurCollector.getQualityBonus()/100); if SulfurCollector.maker then q=q+(SulfurCollector.maker.skill/180) end; q=math.min(2.0,q); SulfurCollector.productStock[m.productType]=(SulfurCollector.productStock[m.productType] or 0)+m.quantity; SulfurCollector.totalProducts=SulfurCollector.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SulfurCollector.maker then SulfurCollector.maker.itemsMade=SulfurCollector.maker.itemsMade+m.quantity; if math.random()<0.20 then SulfurCollector.maker.skill=math.min(100,SulfurCollector.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žveplo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sulfur.completed",{productName=m.productName,purity=m.purity}) end end
function SulfurCollector.update(dt) if not _G.state then return end; SulfurCollector.dayTimer=SulfurCollector.dayTimer+dt; if SulfurCollector.dayTimer>=30 then SulfurCollector.dayTimer=0; for i=#SulfurCollector.activeMaking,1,-1 do local m=SulfurCollector.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SulfurCollector.completeMaking(m); table.remove(SulfurCollector.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SulfurCollector.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SulfurCollector.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SulfurCollector.getStats() return {oreStock=SulfurCollector.oreStock,fuelStock=SulfurCollector.fuelStock,silverStock=SulfurCollector.silverStock,goldStock=SulfurCollector.goldStock,jewelStock=SulfurCollector.jewelStock,productStock=SulfurCollector.productStock,numBuildings=#SulfurCollector.buildings,hasMaker=SulfurCollector.maker~=nil,makerName=SulfurCollector.maker and SulfurCollector.maker.name or "—",makerSkill=SulfurCollector.maker and SulfurCollector.maker.skill or 0,activeMaking=#SulfurCollector.activeMaking,totalProducts=SulfurCollector.totalProducts} end
return SulfurCollector
